/* escreva AQUI as DUAS funcoes.

   1) const int *maiorDe(const int v[], int n)
      com n == 0 devolve NULL (nao ha gaveta para apontar);
      senao acha o indice da maior nota e devolve &v[indice].

   2) int oGateDoNulo(const int *papel)
      devolve 1 quando papel != NULL, e 0 quando o papel
