#include <stdio.h>

/* teste do desafio o-gate-do-nulo — counter_protocol (03-tdd 3.9.3).
   Fase VALOR: sem captura de stdout. Cada cenario chama maiorDe, entrega
   o papel a porteira e COMPARA o papel com o endereco da gaveta esperada
   — sem nunca ir ate a casa de um papel que pode estar em branco (ler o
   valor de um ponteiro nulo e comportamento indefinido, proibido nesta
   trilha). */

/* prototipos das funcoes do aluno (o teste declara o que exercita) */
const int *maiorDe(const int v[], int n);
int oGateDoNulo(const int *papel);

SM_TEST(a_lista_vazia_devolve_papel_em_branco) {
    int notas[4] = {8, 5, 9, 2};
    checa_int("com n = 0 a porteira recusa", oGateDoNulo(maiorDe(notas, 0)), 0,
              "sem gaveta nenhuma para apontar, maiorDe devolve o papel em branco");
    checa_int("papel em branco entregue na mao", oGateDoNulo(NULL), 0,
              "a porteira responde 0 para qualquer papel sem endereco");
}

SM_TEST(a_maior_nota_no_meio) {
    int notas[4] = {8, 5, 9, 2};
    checa_int("a porteira aceita o papel", oGateDoNulo(maiorDe(notas, 4)), 1,
              "com quatro notas existe uma maior, e o papel volta com endereco");
    checa_int("o papel aponta para a gaveta 2", maiorDe(notas, 4) == &notas[2], 1,
              "a maior nota da lista e o 9, que mora na gaveta 2");
}

SM_TEST(a_maior_nota_na_ultima_gaveta) {
    int notas[3] = {4, 6, 7};
    checa_int("a porteira aceita o papel", oGateDoNulo(maiorDe(notas, 3)), 1,
              "a lista tem notas, entao o papel tem endereco");
    checa_int("o papel aponta para a ultima gaveta", maiorDe(notas, 3) == &notas[2], 1,
              "o 7 e a maior nota e mora na ultima gaveta da lista");
}

