#include <stdio.h>

const int *maiorDe(const int v[], int n) {
    if (n == 0) {
        return NULL;
    }
    int melhor = 0;
    for (int i = 1; i < n; i++) {
        if (v[melhor] < v[i]) {
            melhor = i;
        }
    }
    return &v[melhor];
}

int oGateDoNulo(const int *papel) {
    if (papel != NULL) {
        return 1;
    }
    return 0;
}
